sys_script_client.script:
function onLoad() {


	var planned = g_form.getValue('planned_date'); // adjust field name if needed 
	var completed = g_form.getValue('completed'); // adjust field name if needed 

	if (!planned || completed == 'true') { 
		return; 
	} 

	var plannedDate = new GlideDateTime(planned);
	var today = new GlideDateTime(); 
	var tomorrow = new GlideDateTime(); 
	tomorrow.addDaysLocalTime(1); 

	// Normalize all to midnight for clean date-only comparison 
	plannedDate.setDisplayValue(plannedDate.getLocalDate() + " 00:00:00"); 
	today.setDisplayValue(today.getLocalDate() + " 00:00:00"); 
	tomorrow.setDisplayValue(tomorrow.getLocalDate() + " 00:00:00"); 

	// If planned date is today or tomorrow (but not past) 
	if (plannedDate <= tomorrow) { alert("Warning: Planned Completion Date is today or within the next 24 hours, and this record is not completed."); 
	}
}
